    color: rgba(255, 255, 255, 0.45) !important;
    -webkit-text-fill-color: rgba(255, 255, 255, 0.45) !important;
    opacity: 1 !important;
}

/* 右侧工具区 */
.input-action-bar-custom > div:last-child {
    margin-bottom: 0px !important;
    gap: 2px !important;
    height: 100%;
    align-items: center;
}

/* 贴纸/AI/麦克风按钮 */
.input-btn-sticker, .input-btn-ai, .input-btn-mic {
    display: flex !important;
