custom.css:
.page { position: absolute; inset: 0; color: #fff; font-family: -apple-system, "PingFang SC", sans-serif; }
.bg { position: absolute; inset: 0; background: {{accent}} url("{{portrait}}") center top / cover no-repeat; }
.bg::after { content: ""; position: absolute; inset: 0; background: linear-gradient(180deg, rgba(0,0,0,.4), rgba(0,0,0,0) 30%, rgba(0,0,0,0) 55%, rgba(0,0,0,.6)); }
.clock { position: absolute; left: 24px; top: calc(var(--safe-top, 44px) + 16px); }
.clock b { display: block; font-size: 64px; line-height: 1; letter-spacing: -1px; }
.clock small { display: block; margin-top: 6px; font-size: 14px; opacity: .9; }
.card { position: absolute; left: 20px; right: 20px; bottom: 124px; padding: 12px 16px; border-radius: 16px; background: rgba(255,255,255,.92); color: #333; }
.card em { font-style: normal; font-size: 13px; font-weight: 700; color: {{accent}}; }
.card p { margin: 4px 0 0; font-size: 15px; line-height: 1.5; }
.apps { position: absolute; left: 16px; right: 16px; bottom: 44px; display: flex; gap: 10px; }
.app { flex: 1; padding: 14px 0; border-radius: 16px; text-align: center; font-size: 13px; font-weight: 700; background: rgba(0,0,0,.35); border: 1px solid rgba(255,255,255,.35); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.app.start { background: {{accent}}; border-color: transparent; }
@keyframes rise { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: none; } }
@keyframes shine { 0% { background-position: 150% 0; } 60%, 100% { background-position: -50% 0; } }
html.tp-fx:not(.tp-enter) .clock, html.tp-fx:not(.tp-enter) .card, html.tp-fx:not(.tp-enter) .apps { opacity: 0; }
.tp-enter .clock { animation: rise .8s cubic-bezier(.2,.8,.2,1) both; }
.tp-enter .card { animation: rise .8s .15s cubic-bezier(.2,.8,.2,1) both; }
.tp-enter .apps { animation: rise .8s .3s cubic-bezier(.2,.8,.2,1) both; }
.app.start { background-image: linear-gradient(110deg, transparent 35%, rgba(255,255,255,.55) 50%, transparent 65%); background-size: 250% 100%; background-repeat: no-repeat; animation: shine 3s ease-in-out infinite; }

value.css:
/* 仿ios26通知栏v1 — nuojiji notification bar theme */

:root {
    /* ================= 1. 布局调整区 ================= */

    /* 🍷 离灵动岛的距离（数值越大，弹窗越往下掉） */
    --nuo-notif-banner-offset-top: 46px;

    /* 🍷 弹窗的胖瘦（第一个数值是上下留白，第二个是左右。把 12px 改小，弹窗变扁） */
    --nuo-notif-padding: 12px 14px;


    /* ================= 2. 浅色模式（白天）材质区 ================= */

    --nuo-notif-bg: rgba(255, 255, 255, 0.5);
    --nuo-notif-blur: 5px;
    --nuo-notif-saturate: 120%;
    --nuo-notif-brightness: 1.15; 
    --nuo-notif-radius: 24px;
    --nuo-notif-avatar-radius: 10px;    
    --nuo-notif-border: none;
    --nuo-notif-title-color: #000000;
    --nuo-notif-message-color: #000000;
    --nuo-notif-time-color: #666666;
}

/* ================= 3. 长度与绝对居中 ================= */
.nuo-notif-banner-root {
    width: 96% !important; 
    max-width: none !important; 
    left: 50% !important;
    transform: translateX(-50%) !important;
}

/* ================= 4. 深色模式（夜间）材质区 ================= */
@media (prefers-color-scheme: dark) {
    :root {
        --nuo-notif-bg: rgba(0, 0, 0, 0.42) !important;
        --nuo-notif-bg-dark: rgba(0, 0, 0, 0.42) !important;
        --nuo-notif-brightness: 0.6; 
        --nuo-notif-title-color: #ffffff !important;
        --nuo-notif-message-color: rgba(255, 255, 255, 1) !important;
        --nuo-notif-time-color: rgba(255, 255, 255, 0.5) !important;
    }
}

/* ================= 5. 卡片主体：液态上下对冲光 & 投影 ================= */
.ios-notification-banner {
    position: relative !important;

    box-shadow: 
        inset 0 8px 16px rgba(255, 255, 255, 0.4), 
        inset 0 -6px 12px rgba(255, 255, 255, 0.2), 
        inset 0 1px 1px rgba(255, 255, 255, 0.9), 
        0 8px 24px rgba(0, 0, 0, 0.12) !important;

    background: var(--nuo-notif-bg) !important;
    backdrop-filter: blur(var(--nuo-notif-blur)) saturate(var(--nuo-notif-saturate)) brightness(var(--nuo-notif-brightness)) !important;
    border-radius: var(--nuo-notif-radius) !important;
}

@media (prefers-color-scheme: dark) {
    .ios-notification-banner {
        box-shadow: 
            inset 0 8px 16px rgba(255, 255, 255, 0.08),
            inset 0 -6px 12px rgba(255, 255, 255, 0.04),
            inset 0 1px 1px rgba(255, 255, 255, 0.2), 
            0 8px 24px rgba(0, 0, 0, 0.12) !important;
    }
}

/* ================= 6. 头像大小 ================= */
.ios-notification-banner img,
.ios-notification-banner .avatar-img {
    width: 42px !important;
    height: 42px !important;
    flex-shrink: 0 !important;
    border-radius: var(--nuo-notif-avatar-radius) !important;
}

/* ================= 7. 边缘折射层（产生玻璃边缘色彩扭曲） ================= */
.ios-notification-banner::after {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: inherit;
    pointer-events: none;
    border: 1px solid rgba(255, 255, 255, 0.2);
    box-shadow: inset 0 0 0 0.5px rgba(255, 255, 255, 0.3);
    mix-blend-mode: overlay;
}

@media (prefers-color-scheme: dark) {
    .ios-notification-banner::after {
        border: 1px solid rgba(255, 255, 255, 0.08);
        box-shadow: inset 0 0 0 0.5px rgba(255, 255, 255, 0.1);
        mix-blend-mode: plus-lighter;
    }
}

