:root {
    --rp-disc-size: 220px;
    --rp-disc-bg: #0d0d0d;
    --rp-disc-radius: 18px;      /* 唱片變方卡 */
    --rp-cover-size: 220px;
    --rp-cover-radius: 18px;
    --rp-scrubber-height: 2px;
    --rp-scrubber-bg: rgba(255,255,255,0.18);
    --rp-scrubber-fill: #fff;
}

/* 背景去色，安靜一點 */
.bg-img { filter: grayscale(1) blur(60px) brightness(0.5) !important; }
.bg-overlay { background: linear-gradient(180deg, rgba(0,0,0,0.35), rgba(0,0,0,0.92)) !important; }

/* 唱針、唱片紋路都收掉，只留封面 */
.tonearm-container { display: none !important; }
.vinyl-disc { box-shadow: 0 20px 60px rgba(0,0,0,0.7) !important; border: none !important; }
.vinyl-disc::before, .vinyl-disc::after { display: none !important; }
.vinyl-disc.spinning { animation: none !important; }   /* 方卡不轉 */

.rp-header-title { opacity: 0 !important; }            /* 頂部標題留白 */
.rp-song-title {
    font-size: 28px !important;
    font-weight: 300 !important;
    letter-spacing: 3px !important;
}
.rp-song-artist { letter-spacing: 2px !important; opacity: 0.6 !important; }
.rp-now-playing { display: none !important; }
.rp-time-row { opacity: 0.45 !important; }
.rp-lyric { font-weight: 400 !important; letter-spacing: 1px !important; opacity: 0.8 !important; }

/* ── 電台直播：同樣去色安靜 ── */
.floating-live-badge { background: rgba(0,0,0,0.45) !important; border-color: rgba(255,255,255,0.2) !important; box-shadow: none !important; }
.live-dot { background: #fff !important; box-shadow: none !important; }
.mic-badge, .mic-badge.active { background: rgba(0,0,0,0.5) !important; border-color: rgba(255,255,255,0.2) !important; color: rgba(255,255,255,0.75) !important; }
.mic-badge.active svg { color: rgba(255,255,255,0.75) !important; }
.sound-ripple { border-color: rgba(255,255,255,0.35) !important; }
.pulsing-img { border-color: rgba(255,255,255,0.9) !important; box-shadow: none !important; }
.freq-bar-active { background: rgba(255,255,255,0.85) !important; }
.danmaku-layer { display: none !important; }          /* 安靜模式關彈幕 */

/* ── AI 電台直播 ── */
.arl-seg-text { font-weight: 300 !important; letter-spacing: 1px !important; }
.arl-seg-name { letter-spacing: 2px !important; }
.host-role-badge, .host-role-badge.gold { color: #fff !important; border-color: rgba(255,255,255,0.4) !important; }
.premium-glow-ring { border-color: rgba(255,255,255,0.35) !important; }

