/* ───────── 白色小卡片 ───────── */
.xt-card {
  position: relative;
  background: #fff !important;
  border: none !important;
  border-radius: 4px;
  padding: 12px 14px 14px !important;
  margin: 0 0 12px;
  backdrop-filter: none;
  box-shadow: 0 0 0 1px rgba(238,236,242,.9), 0 3px 16px rgba(200,195,212,.14);
}
.xt-card::before {
  content: "♡";
  position: absolute;
  right: 14px; top: 11px;
  font-size: 11px;
  line-height: 1;
  color: #e2dfe9;
  pointer-events: none;
}
.xt-card-title {
  font-family: var(--xt-serif);
  font-style: italic;
  font-weight: 400;
  font-size: 14px;
  letter-spacing: .6px;
  color: #a3a3ad;
  margin: 0 0 8px;
  text-transform: none;
}
.xt-card-title::before { content: "+ "; }

.xt-text {
  background: none !important;
  border: none !important;
  padding: 0 !important;
  font-style: normal;
  font-size: 13px;
  line-height: 1.95;
  color: #6e6e77;
  text-align: left;
}

/* ───────── 标签（眼神 / 情绪） ───────── */
.xt-tags { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }
.xt-tag {
  background: #faf9fb !important;
  border: 1px solid #efedf3 !important;
  border-radius: 20px;
  padding: 2px 11px !important;
  font-size: 11px;
  letter-spacing: .5px;
  color: #9b9ba6;
}
.xt-tag-eyeDirection::before { content: "◦ "; }
.xt-tag-mood::before { content: "+ "; }

/* ───────── 列表（三句话 / 穿搭） ───────── */
.xt-list { counter-reset: s; }
.xt-list-item {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: 7px 0 !important;
  background: none !important;
  border: none !important;
  border-bottom: 1px solid #f1eff4 !important;
  font-size: 13px;
  line-height: 1.85;
  color: #6e6e77;
}
.xt-list-item:last-child { border-bottom: none !important; }
.xt-list-check { display: none !important; }
.xt-list-item::before {
  counter-increment: s;
  content: "0" counter(s);
  flex: none;
  min-width: 22px;
  font-family: var(--xt-serif);
  font-style: italic;
  font-size: 13px;
  color: #b5b5c0;
}
/* 穿搭：换成部位名 */
.xt-collapse-3 .xt-list-item::before { min-width: 64px; font-size: 12px; letter-spacing: .5px; }
.xt-collapse-3 .xt-list-item:nth-child(1)::before { content: "top"; }
.xt-collapse-3 .xt-list-item:nth-child(2)::before { content: "bottom"; }
.xt-collapse-3 .xt-list-item:nth-child(3)::before { content: "shoes"; }
.xt-collapse-3 .xt-list-item:nth-child(4)::before { content: "accessory"; }
.xt-collapse-3 .xt-list-item:nth-child(5)::before { content: "scent"; }

/* ───────── 附言类文字（无卡片的单行） ───────── */
.xt-text-unsent, .xt-text-outfitNote, .xt-text-verdict {
  margin: 2px 4px 12px !important;
  font-family: var(--xt-serif);
  font-style: italic !important;
  font-size: 13px !important;
  letter-spacing: .4px;
  color: #a9a9b4 !important;
}
.xt-text-unsent::before { content: "deleted · "; }
.xt-text-unsent { text-decoration: line-through; text-decoration-color: rgba(170,170,184,.5); }
.xt-text-outfitNote::before { content: "note · "; }
.xt-text-verdict::before { content: "verdict · "; }

/* ───────── 天使 / 恶魔 ───────── */
.xt-collapse-4 .xt-card:nth-child(1) { background: #fff !important; }
.xt-collapse-4 .xt-card:nth-child(2) { background: #f4f3f7 !important; }
.xt-collapse-4 .xt-card:nth-child(2) .xt-card-title { color: #8f8f9c; }

/* ───────── 数据 ───────── */
.xt-grid { gap: 10px; margin-bottom: 10px; }
.xt-grid-stat, .xt-grid-bar { background: #faf9fb !important; border: none !important; border-radius: 3px; }
.xt-grid-stat-value { font-family: var(--xt-serif); font-style: italic; font-size: 20px; color: #6e6e77; }
.xt-grid-stat-label { font-size: 10px; letter-spacing: 2px; color: #bdbdc6; text-transform: uppercase; }
.xt-bar-track { background: #f1eff4; height: 3px; border-radius: 3px; }
.xt-bar-fill { background: linear-gradient(90deg, #dcdbe4, #a9a9b6); border-radius: 3px; }

/* ───────── 底部 ───────── */
.xt-footer {
  border: none !important;
  font-family: var(--xt-serif);
  font-style: italic;
  font-size: 12px;
  letter-spacing: 3px;
  color: #cbcbd4;
  padding: 2px 0 12px;
}

/* ───────── 内容字体（只作用于正文内容） ───────── */
.xt-text, .xt-list-item, .xt-tag {
  font-family: var(--xt-body) !important;
  font-weight: 300;
}
.xt-text-unsent, .xt-text-outfitNote, .xt-text-verdict {
  font-family: var(--xt-body) !important;
  font-style: normal !important;
}
.xt-text-unsent::before, .xt-text-outfitNote::before, .xt-text-verdict::before {
  font-family: var(--xt-serif);
  font-style: italic;
}

