}
.voice-waveform-bar {
    background: #333333 !important;
}
.voice-duration {
    color: #333333 !important;
}

data.css:
body {
  margin: 0;
  padding: 8px; /* 根據需要調整邊距 */
  box-sizing: border-box;
}

.container {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  gap: 8px; /* 膠囊之間的安全間距 */
}

.pill {
  flex: 1;
  border-radius: 999px; /* 呈現完美的膠囊形狀 */
  background-position: center;
  background-size: cover;
  background-repeat: no-repeat;
  overflow: hidden;
  background-color: #f1f1f1;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  background: transparent;
  width: 100%; height: 100%;
  font-family: 'Georgia', serif;
}

.widget {
  width: calc(100% - 24px);
  height: calc(100% - 24px);
  display: flex; flex-direction: column;
  background: transparent;
  border-radius: 12px;
  padding: 20px 18px;
  margin: 12px;
  border: 1.5px dashed #c8c0b8;
  position: relative;
  overflow: visible;
  box-sizing: border-box;
}

/* ── 八个角块，骑在虚线上 ── */
.corner {
  position: absolute;
  width: 8px; height: 8px;
  border: 1.5px solid #b0a898;
  background: transparent;
  pointer-events: none;
  z-index: 2;
}
.corner.tl { top: -4px;  left: -4px; }
.corner.tr { top: -4px;  right: -4px; }
.corner.bl { bottom: -4px; left: -4px; }
.corner.br { bottom: -4px; right: -4px; }
.corner.tm { top: -4px;    left: 50%; transform: translateX(-50%); }
.corner.bm { bottom: -4px; left: 50%; transform: translateX(-50%); }
.corner.ml { left: -4px;   top: 50%;  transform: translateY(-50%); }
.corner.mr { right: -4px;  top: 50%;  transform: translateY(-50%); }

/* ── 引用区 ── */
.quote-area {
  flex: 0 0 46%;
  display: flex; flex-direction: column;
  justify-content: center;
  align-items: center;
  overflow: hidden;
}

.star-deco {
  display: flex; align-items: center; gap: 4px;
  color: #a09080;
  margin-bottom: 5px;
  justify-content: flex-start;
  width: 100%;
}
.star-icon  { width: 14px; height: 14px; }
.dot-icon   { width: 6px;  height: 6px; }
.cross-icon { width: 11px; height: 11px; }

.quote-text {
  font-size: 13px;
  font-style: italic;
  color: #2a2a2a;
  line-height: 1.65;
  letter-spacing: 0.2px;
  text-align: center;
  width: 100%;
}
.quote-text sup {
  font-size: 6px; color: #bbb; vertical-align: super;
}
.inline-cross {
  width: 9px; height: 9px;
  display: inline; vertical-align: middle;
  color: #a09080;
}

/* ── 分隔线 ── */
.divider {
  width: 100%; height: 1px;
  background: #e0d8d0;
  flex-shrink: 0;
  margin: 2px 0 4px;
}

/* ── 歌词区 ── */
.lyrics-area {
  flex: 1;
  display: flex; flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 4px;
  min-height: 0;
  overflow: hidden;
}
.lyric-line {
  font-size: 10px;
  color: #666;
  text-align: center;
  line-height: 1.6;
  letter-spacing: 0.2px;
  font-family: 'Georgia', serif;
  width: 100%;
}
.lyric-line:last-child {
  font-size: 8.5px;
  color: #aaa;
  margin-top: 2px;
  letter-spacing: 0.8px;
}

* { margin: 0; padding: 0; box-sizing: border-box; }
html, body {
  width: 100%; height: 100%;
  background: transparent;
  display: flex; align-items: center; justify-content: center;
  font-family: system-ui, sans-serif;
}
.container {
  width: 100%; height: 100%;
  display: flex; flex-direction: column;
  align-items: center; justify-content: center;
  padding: 10px 14px;
  gap: 6px;
}
.label {
  font-size: 9px; font-weight: 700;
  color: #222; letter-spacing: 0.04em;
}
.bar-wrap {
  width: 100%; height: 22px;
  border-radius: 99px;
  border: 2px solid #222;
  overflow: hidden;
  position: relative;
  background: #fff;
}
.bar-fill {
  position: absolute; top: 0; left: 0;
  height: 100%; width: 60%;
  border-radius: 99px;
  background: linear-gradient(to right, #fff 0%, #111 100%);
}
.bar-icons {
  position: absolute; top: 0; left: 0;
  width: 100%; height: 100%;
  display: flex; align-items: center;
  justify-content: space-around;
  padding: 0 10px;
  pointer-events: none;
}

.my-custom-box {
  width: 100%;
  height: 100%;
  background: #ffffff;
  border-radius: 7vw;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  font-family: -apple-system, BlinkMacSystemFont, sans-serif;
  box-sizing: border-box;
  padding: 3.5vw 4vw 2.5vw;
}

/* 顶部用户信息 */
.tweet-header {
  display: flex;
  align-items: center;
  gap: 2.5vw;
  flex-shrink: 0;
}

.tweet-avatar {
  width: 13vw;
  height: 13vw;
  border-radius: 50%;
  object-fit: cover;
  flex-shrink: 0;
}

.tweet-user {
  display: flex;
  flex-direction: column;
  flex: 1;
}

.tweet-name-row {
  display: flex;
  align-items: center;
  gap: 1vw;
}

.tweet-name {
  font-size: 4vw;
