}

.translate-link {
  color: #1d9bf0;
  font-weight: 600;
}

.tweet-translate-text {
  margin: 0;
  font-size: 2.8vw;
  color: #0f1419;
}

.tweet-tag {
  display: inline-block;
  background: #e7e7e7;
  border-radius: 10vw;
  padding: 0.6vw 2.5vw;
  font-size: 2.8vw;
